record.field:
for rec in records.sudo():
    employee = rec.x_employee_id.sudo() if rec.x_employee_id else False
    if not employee:
        continue

    employee_name = employee.name or employee.display_name or ''
    document_number = rec.x_document_number or ''
    document_type_label = {
        'id_card': 'ID Card / بطاقة شخصية',
        'passport': 'Passport / جواز سفر',
        'driving_license': 'Driving License / رخصة قيادة',
        'company_id_card': 'Company ID Card / بطاقة الشركة',
    }.get(rec.x_document_type or '', rec.x_document_type or 'هوية')

    name_parts = []
    if employee_name:
        name_parts.append(employee_name)
    if document_type_label:
        name_parts.append(document_type_label)
    if document_number:
        name_parts.append(document_number)

    normalized_name = ' - '.join(name_parts) or 'هوية'

    if normalized_name and rec.x_name != normalized_name:
        rec.sudo().write({'x_name': normalized_name})

    display_name = rec.x_name or normalized_name or employee_name or 'هوية'
    body = 'تم تحديث بيانات الهوية: %s' % display_name

    attachment_ids = []
    if rec.x_source_attachment_id:
        attachment_ids.append(rec.x_source_attachment_id.id)

    if attachment_ids:
        employee.message_post(body=body, subtype_xmlid='mail.mt_note', attachment_ids=attachment_ids)
    else:
        employee.message_post(body=body, subtype_xmlid='mail.mt_note')

